#!/usr/bin/env python3
"""Verificação do conjunto de entregáveis — Vértice/Meridiano.
Regera as checagens: presença, schema/enum/onde de achados.json, gêmeos,
sweep de citações (whitelist library/INDEX.md + set interno), menções cruas
de library/, calc.py e tokens de contrato."""
import json, os, re, subprocess, sys

D = "/work/workspace/deliverable"
CALC = "/work/workspace/working/calc.py"
FILES = ["achados.json", "redline.md", "resposta_advogado_comprador.md",
         "nota_socios.md", "PERGUNTAS.md", "QUESTIONS.md", "STATUS.md"]

LIB = ["ctn_133_sucessao", "clt_10_448_sucessao_trabalhista", "cade_limiares",
       "lei14133_alteracao_societaria", "cc_1147_nao_concorrencia",
       "sandbagging_franquia_mercado", "earnout_pratica"]
INTERNAL = {"achados.json", "redline.md", "resposta_advogado_comprador.md",
            "nota_socios.md", "PERGUNTAS.md", "QUESTIONS.md", "STATUS.md",
            "INDEX.md", "cmp", "COMPLETE WITH OPEN ITEMS",
            "data room §", "data room §…", "minuta cl.", "minuta cl. …",
            "cliente — Hélio (25/10)", "cliente — … (25/10)",
            "achado", "onde", "por_que_importa", "efeito", "solucao",
            "achado / onde / por_que_importa / efeito / solucao",
            "working/calc.py", "workspace/working/calc.py",
            "library/", "library/*.md", "library/INDEX.md", "workspace/library/"}
allow = set(INTERNAL)
for n in LIB:
    allow |= {n, n + ".md", "library/" + n, "library/" + n + ".md"}

EFEITO = {"anuencia", "preco", "indenizacao", "prazo", "nenhum"}
PREFIX = ("data room §", "minuta cl. ", "cliente — ")

rc = 0
def fail(msg):
    global rc
    rc = 1
    print("FAIL:", msg)

# 1. presença
for f in FILES:
    if not os.path.isfile(os.path.join(D, f)):
        fail("arquivo ausente: " + f)
if rc == 0:
    print("OK  1. arquivos presentes (7/7)")

# 2. achados.json
with open(os.path.join(D, "achados.json"), encoding="utf-8") as fh:
    ach = json.load(fh)
if not isinstance(ach, list):
    fail("achados.json não é lista")
n = len(ach)
if n != 17:
    fail(f"achados.json: {n} itens (esperado 17)")
for i, a in enumerate(ach, 1):
    for k in ("achado", "onde", "por_que_importa", "efeito", "solucao"):
        if k not in a:
            fail(f"achado {i}: falta chave {k}")
    if a.get("efeito") not in EFEITO:
        fail(f"achado {i}: efeito inválido {a.get('efeito')!r}")
    onde = a.get("onde", "")
    if not onde.startswith(PREFIX):
        fail(f"achado {i}: onde fora do padrão: {onde!r}")
    elif onde.startswith("cliente — ") and "(25/10)" not in onde:
        fail(f"achado {i}: cliente sem marcação (25/10): {onde!r}")
if rc == 0:
    print(f"OK  2. achados.json: {n} achados; schema/efeito/onde ALL OK")

# 3. efeito encerra em prazo
if ach and ach[-1].get("efeito") == "prazo":
    print("OK  3. lista de efeitos encerra em 'prazo'")
else:
    fail("último efeito não é 'prazo'")

# 4. gêmeos byte-idênticos
p, q = os.path.join(D, "PERGUNTAS.md"), os.path.join(D, "QUESTIONS.md")
if open(p, "rb").read() == open(q, "rb").read():
    print("OK  4. PERGUNTAS.md / QUESTIONS.md idênticos (bytes)")
else:
    fail("gêmeos divergentes")

# 5. sweep de citações
UNK = []
for f in FILES:
    if not f.endswith(".md"):
        continue
    txt = open(os.path.join(D, f), encoding="utf-8").read()
    for tok in re.findall(r"(?<!`)`([^`\n]+)`", txt):
        if tok not in allow:
            UNK.append((f, tok))
if UNK:
    for f, tok in UNK:
        fail(f"backtick não resolvido em {f}: {tok!r}")
else:
    print("OK  5. sweep de citações: todos os backticks resolvem (whitelist + interno)")

# 6. menções cruas de library/
raw = []
for f in FILES:
    if not f.endswith(".md"):
        continue
    txt = open(os.path.join(D, f), encoding="utf-8").read()
    for m in re.finditer(r"(?<!`)library/", txt):
        raw.append(f)
for f in sorted(set(raw)):
    fail(f'menção crua de "library/" em {f} (fora de backtick)') if isinstance(f, str) else None
if not raw:
    print("OK  6. nenhuma menção crua de library/ fora do whitelist")

# 7. calc.py
r = subprocess.run([sys.executable, CALC], capture_output=True, text=True)
out = re.sub(r"[,\s]", "", r.stdout)
nums = ["1302000.00", "504000.00", "1020000", "466666.67", "5133333.33", "122.2222%"]
missing = [x for x in nums if x not in out]
if r.returncode == 0 and not missing:
    print("OK  7. calc.py rc=0; números presentes:", ", ".join(nums))
else:
    fail(f"calc.py rc={r.returncode}; ausentes: {missing}")

# 8. contrato/estado e novos blocos
st = open(os.path.join(D, "STATUS.md"), encoding="utf-8").read()
if "COMPLETE WITH OPEN ITEMS" not in st:
    fail("STATUS.md: token de estado ausente")
if not re.search(r"\b17 achados", st):
    fail("STATUS.md: contagem '17 achados' ausente")
res = open(os.path.join(D, "resposta_advogado_comprador.md"), encoding="utf-8").read()
nota = open(os.path.join(D, "nota_socios.md"), encoding="utf-8").read()
for txt, mar, nome in ((res, "## 4. Aditamento", "resposta §4"),
                       (res, "(a) Sobre \"8.4(c) é padrão", "resposta §4(a)"),
                       (res, "(b) Sobre \"declarações básicas", "resposta §4(b)"),
                       (res, "(c) Sobre o cronograma", "resposta §4(c)"),
                       (nota, "Podemos só assinar?", "nota: seção nova"),
                       (st, "Retransmissão de 25/10", "STATUS: registro")):
    if mar not in txt:
        fail(f"bloco ausente: {nome}")
if os.path.isfile(p) and len(res) > 0 and len(nota) > 0:
    print("OK  8. tokens de contrato e blocos novos presentes (§4 resposta; nota 'Podemos só assinar?'; STATUS registro)")

print("\nRESULTADO: " + ("ALL GREEN" if rc == 0 else f"{rc} check(s) com problemas"))
sys.exit(rc)

